"use strict";

// The RWF-020/RWF-022 interaction, isolated.
//
// `Valid` is the plain case: a real superclass, nothing withdrawn,
// module completes -- and the key still has to run.
//
// `Invalid` is the one the RWF-022 audit turned up. `makeInvalid()`
// returns `1`, so the class definition ultimately throws
// `TypeError: Class extends value 1 is not a constructor or null` --
// but ONLY AFTER the computed keys have already been evaluated. RWF-022
// correctly withdraws the authority of any export written below this
// point; that is a statement about later EXPORTS and says nothing about
// the sink the key already reached. The target must not be lost merely
// because a cutoff family fired further down the same statement.
const danger = require("./danger");

class ValidBase {}

function makeInvalid() {
  return 1;
}

function validKey() {
  danger.explode("valid-heritage-key");
  return "x";
}

function invalidKey() {
  danger.explode("invalid-heritage-key");
  return "y";
}

class Valid extends ValidBase {
  [validKey()]() {}
}

class Invalid extends makeInvalid() {
  [invalidKey()]() {}
}

module.exports = { Valid, Invalid };
